  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 16, 'Da equação à quantidade de produto', 'Balanceie primeiro. Converta massa em mol, aplique a razão dos coeficientes e só então converta a unidade pedida.', '## 1. O que a equação informa
Em uma equação balanceada, os coeficientes dão a proporção entre quantidades de partículas e de mol. Em N₂ + 3 H₂ → 2 NH₃, cada proporção de 1 mol de N₂ para 3 mol de H₂ pode formar 2 mol de NH₃. A proporção pode ser ampliada ou reduzida; os coeficientes não fixam uma quantidade absoluta nem indicam a velocidade da reação.

## 2. Balanceie antes de calcular
A equação precisa conservar o número de átomos de cada elemento. Ao balancear, alteramos coeficientes, nunca os índices dentro de uma fórmula: trocar H₂O por H₂O₂ mudaria a substância. Use somente os coeficientes de uma equação balanceada para obter fatores estequiométricos.

## 3. De massa para massa
Os coeficientes relacionam mol, não gramas diretamente. Para uma massa conhecida, calcule n = m/M. Use então a razão molar da equação para chegar aos mol da substância desejada. Se a resposta pede massa, finalize com m = n × M. Em cada etapa, acompanhe as unidades para que as unidades intermediárias se cancelem.

## 4. Encontre o reagente limitante
Quando há mais de um reagente, calcule quanto produto cada um poderia formar, mantendo os outros suficientes. O reagente que prevê a menor quantidade de produto é o limitante; ele determina o rendimento teórico. Não compare somente as massas nem escolha automaticamente o menor número de mol: leve em conta os coeficientes e, se a resposta exigir massa, as massas molares.

## 5. Exemplo resolvido e rendimento
Considere 2 Al + 3 Cl₂ → 2 AlCl₃. Com 54 g de Al e 284 g de Cl₂, usando M(Al)=27 g/mol e M(Cl₂)=71 g/mol, temos 2 mol de Al e 4 mol de Cl₂. Dois mol de Al exigem 3 mol de Cl₂, então o alumínio limita. A proporção prevê 2 mol de AlCl₃. Se M(AlCl₃)=133,5 g/mol, o rendimento teórico é 267 g. Se o experimento recuperar 213,6 g de produto puro e seco, o rendimento percentual é 213,6/267 × 100 = 80%. O rendimento real pode ser menor por perdas ou reação incompleta; um valor aparente acima do teórico exige verificar pureza, secagem, medição e modelo.',
    'Para 2 Al + 3 Cl₂ → 2 AlCl₃, converta 54 g Al em 2 mol e 284 g Cl₂ em 4 mol. Compare as capacidades: 2/2 = 1 para Al e 4/3 ≈ 1,33 para Cl₂. O menor fator é o do Al; logo, Al é limitante. Ele forma 2 mol AlCl₃. Com 133,5 g/mol, isso corresponde a 267 g teóricos. Uma recuperação de 213,6 g dá 80% de rendimento.', array['Confira átomos e balanceamento antes da conta.', 'Escreva os fatores como frações com unidades.', 'Para cada reagente, estime o produto possível e compare.', 'Converta para gramas apenas no fim, quando essa for a unidade pedida.', 'Mantenha rendimento real, teórico e percentual como grandezas diferentes.']::text[], 25, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"v16-chemistry-stoichiometry","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Ler fórmulas químicas e reconhecer coeficientes e índices.","Calcular massa molar e usar n = m/M.","Trabalhar com proporções, frações e porcentagens."],"key_concepts":["coeficientes como proporções molares","equação balanceada e conservação de átomos","cadeia massa-mol-mol-massa","reagente limitante e rendimento teórico","rendimento real e rendimento percentual"],"progression":[{"stage":"FOUNDATION","focus":"A sequência reutiliza sondagens existentes; retome coeficientes, unidades e proporções se necessário.","questionIds":[]},{"stage":"APPLICATION","focus":"Aplicar razões molares em cálculos diretos e conversões entre massa e mol.","questionIds":["v5-chem-stoich-practice-01","v5-chem-stoich-practice-02","v5-chem-stoich-practice-03","v5-chem-stoich-practice-04","v5-chem-stoich-practice-05"]},{"stage":"TRANSFER","focus":"Levar o método a processos de produção, neutralização, decomposição e recuperação.","questionIds":["v5-chem-stoich-transfer-01","v5-chem-stoich-transfer-02","v5-chem-stoich-transfer-03","v5-chem-stoich-transfer-04","v5-chem-stoich-transfer-05","v16-chemistry-stoichiometry-051","v16-chemistry-stoichiometry-052","v16-chemistry-stoichiometry-053","v16-chemistry-stoichiometry-054","v16-chemistry-stoichiometry-055","v16-chemistry-stoichiometry-056","v16-chemistry-stoichiometry-057","v16-chemistry-stoichiometry-058","v16-chemistry-stoichiometry-059","v16-chemistry-stoichiometry-060","v16-chemistry-stoichiometry-061","v16-chemistry-stoichiometry-062","v16-chemistry-stoichiometry-063","v16-chemistry-stoichiometry-064","v16-chemistry-stoichiometry-065","v16-chemistry-stoichiometry-066","v16-chemistry-stoichiometry-067","v16-chemistry-stoichiometry-068","v16-chemistry-stoichiometry-069","v16-chemistry-stoichiometry-070","v16-chemistry-stoichiometry-071","v16-chemistry-stoichiometry-072","v16-chemistry-stoichiometry-073","v16-chemistry-stoichiometry-074","v16-chemistry-stoichiometry-075"]},{"stage":"INTEGRATION","focus":"Combinar massas molares, limitante, produto teórico e rendimento real.","questionIds":["v5-chem-stoich-lock-01","v5-chem-stoich-lock-02","v5-chem-stoich-lock-03"]},{"stage":"SPACED_REVIEW_CANDIDATE","focus":"Recuperar distinções e aplicar o raciocínio em novos contextos e tempos de revisão.","questionIds":["v5-chem-stoich-review-01","v5-chem-stoich-review-02","v5-chem-stoich-review-03","v5-chem-stoich-review-04","v5-chem-stoich-review-05"]}],"micro_explanations":[{"trigger":"COEFFICIENT_RATIO","text":"Coeficientes dão uma razão escalável entre mol; não são uma quantidade absoluta."},{"trigger":"BALANCE_BEFORE_CALCULATION","text":"Balanceie mudando coeficientes, nunca os índices que definem as fórmulas."},{"trigger":"MASS_TO_MOLE","text":"Converta a massa conhecida em mol com n = m/M antes de usar a proporção da equação."},{"trigger":"LIMITING_REACTANT","text":"O limitante é o reagente que, respeitada a proporção, permite formar menos produto."},{"trigger":"MOLE_TO_MASS","text":"Depois da razão molar, converta os mol do produto em gramas usando sua massa molar."},{"trigger":"PERCENT_YIELD","text":"Rendimento percentual compara o valor real ao teórico: real ÷ teórico × 100."}],"remediations":[{"id":"COEFFICIENT_VS_SUBSCRIPT","misconception":"INDICE_CONFUNDIDO_COM_COEFICIENTE","prompt":"Marque o número que pode ser ajustado no balanceamento e conte os átomos dentro de cada fórmula sem alterá-la."},{"id":"UNIT_CHAIN","misconception":"MASSA_USADA_COMO_MOL","prompt":"Escreva a cadeia g da substância conhecida → mol conhecida → mol desejado → g desejado, anotando unidades em cada etapa."},{"id":"LIMITING_CAPACITY","misconception":"LIMITANTE_ESCOLHIDO_PELA_MASSA","prompt":"Calcule o produto possível a partir de cada reagente e compare as duas previsões."},{"id":"YIELD_RATIO","misconception":"RENDIMENTO_PERCENTUAL_INVERTIDO","prompt":"Identifique a quantidade real e a teórica, escreva real/teórica × 100 e estime se o resultado faz sentido."}],"review_windows_days":[1,3,7],"review_schedule_status":"SUGGESTED_NOT_AUTOMATED","source_dossier":[{"title":"IUPAC Gold Book: stoichiometry (S06026)","publisher":"International Union of Pure and Applied Chemistry","url":"https://goldbook.iupac.org/terms/view/S06026","accessedOn":"2026-10-13","supports":["A equação estequiométrica relaciona quantidades de reagentes e produtos pelos coeficientes."],"use":"Conferência da definição e do significado quantitativo dos coeficientes; itens do pacote são autorais."},{"title":"Chemistry 2e, Section 4.3: Reaction Stoichiometry","publisher":"OpenStax","url":"https://openstax.org/books/chemistry-2e/pages/4-3-reaction-stoichiometry","accessedOn":"2026-10-13","supports":["Equações balanceadas fornecem fatores estequiométricos para converter quantidades de reagentes e produtos; cálculos podem relacionar mol e massa."],"use":"Conferência conceitual do fluxo de cálculo; exemplos, valores e questões deste pacote foram escritos independentemente."},{"title":"Chemistry 2e, Section 4.4: Reaction Yields","publisher":"OpenStax","url":"https://openstax.org/books/chemistry-2e/pages/4-4-reaction-yields","accessedOn":"2026-10-13","supports":["O reagente limitante determina a quantidade teórica de produto; rendimento real e teórico fundamentam o rendimento percentual."],"use":"Conferência dos conceitos de limitante e rendimento; texto e questões do pacote são autorais."}],"copyright_note":"Questões, números, cenários e explicações são autorais. As fontes conferem conceitos; revisão pedagógica humana permanece pendente e nenhum alinhamento BNCC oficial é reivindicado. Lote V16 autoral com 100 questões e revisão pedagógica pendente; publicação mantida em STAGING.","objective":"Usar uma equação balanceada e quantidades fornecidas para relacionar mols, massas, reagente limitante e rendimento.","common_mistake":"Aplicar a razão dos coeficientes diretamente a gramas ou decidir o limitante apenas pela menor massa ou quantidade em mol.","estimated_minutes":25}'::jsonb
  ) on conflict (canonical_skill_id, version) do nothing;
  select id into v_lesson_id from public.learning_skill_lessons
   where canonical_skill_id = v_skill_id and version = 16
     and metadata->>'content_id' = 'v16-chemistry-stoichiometry' and active = false;
  if v_lesson_id is null then raise exception 'V5_CONTENT_LESSON_CONFLICT'; end if;

  for v_question in
    select * from jsonb_to_recordset('[{"id":"v5-chem-stoich-practice-01","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"APPLY","contextFamily":"ALUMINUM_CHLORIDE_MOLE_RATIO","statement":"Na equação balanceada 2 Al + 3 Cl₂ → 2 AlCl₃, o alumínio está em excesso. Se 9 mol de Cl₂ reagirem completamente, quantos mol de AlCl₃ podem se formar?","options":["6 mol","3 mol","9 mol","12 mol"],"correctAnswer":"6 mol","explanation":"A razão entre Cl₂ e AlCl₃ é 3:2. Multiplicando os dois coeficientes por 3, 9 mol de Cl₂ correspondem a 6 mol de AlCl₃.","errorFocus":"Usar o coeficiente do reagente como se fosse a quantidade de produto.","hint":"Escreva a fração molar produto/reagente com os coeficientes 2/3 e aplique-a a 9 mol de Cl₂.","misconceptions":{"3 mol":["USAR_O_COEFICIENTE_DO_REAGENTE_COMO_SE_FOSSE_A_QUANTIDADE_DE_PRODUTO"]},"position":1},{"id":"v5-chem-stoich-practice-02","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"CALCULATE","contextFamily":"METHANE_MASS_TO_CARBON_DIOXIDE","statement":"Na combustão CH₄ + 2 O₂ → CO₂ + 2 H₂O, há oxigênio suficiente. Considere M(CH₄) = 16 g/mol e M(CO₂) = 44 g/mol. Que massa de CO₂ pode ser formada a partir de 32 g de CH₄?","options":["44 g","32 g","88 g","16 g"],"correctAnswer":"88 g","explanation":"32 g de CH₄ equivalem a 2 mol. A razão CH₄:CO₂ é 1:1, então formam-se 2 mol de CO₂; 2 × 44 g/mol = 88 g.","errorFocus":"Converter massa diretamente pela razão dos coeficientes, sem passar por mol.","hint":"Faça a cadeia g CH₄ → mol CH₄ → mol CO₂ → g CO₂ e confira o cancelamento das unidades.","misconceptions":{"44 g":["CONVERTER_MASSA_DIRETAMENTE_PELA_RAZ_O_DOS_COEFICIENTES_SEM_PASSAR_POR_MOL"]},"position":2},{"id":"v5-chem-stoich-practice-03","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"APPLY","contextFamily":"IRON_OXIDE_CO_REDUCTION","statement":"Na reação balanceada Fe₂O₃ + 3 CO → 2 Fe + 3 CO₂, o CO está em excesso. Partindo de 1,5 mol de Fe₂O₃, qual é a quantidade máxima de ferro produzida?","options":["1,5 mol","3 mol","4,5 mol","6 mol"],"correctAnswer":"3 mol","explanation":"A equação relaciona 1 mol de Fe₂O₃ a 2 mol de Fe. Assim, 1,5 mol × 2 = 3 mol de Fe.","errorFocus":"Achar que os coeficientes descrevem uma única reação indivisível, sem poder escalar a proporção.","hint":"Compare os coeficientes de Fe₂O₃ e Fe: para cada 1 mol do primeiro, formam-se 2 mol do segundo.","misconceptions":{"1,5 mol":["ACHAR_QUE_OS_COEFICIENTES_DESCREVEM_UMA_NICA_REA_O_INDIVIS_VEL_SEM_PODER_ESCALAR_A_PROPOR_O"]},"position":3},{"id":"v5-chem-stoich-practice-04","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"CALCULATE","contextFamily":"POTASSIUM_CHLORATE_OXYGEN","statement":"A decomposição é 2 KClO₃ → 2 KCl + 3 O₂. Se 4 mol de KClO₃ se decompõem completamente, quantos mol de O₂ são formados?","options":["3 mol","4 mol","8 mol","6 mol"],"correctAnswer":"6 mol","explanation":"A razão KClO₃:O₂ é 2:3. Duplicar 2 mol para 4 mol também duplica 3 mol para 6 mol.","errorFocus":"Trocar a razão produto/reagente ou ignorar o coeficiente 3 do oxigênio.","hint":"Use 3 mol O₂ / 2 mol KClO₃ como fator e multiplique por 4 mol KClO₃.","misconceptions":{"3 mol":["TROCAR_A_RAZ_O_PRODUTO_REAGENTE_OU_IGNORAR_O_COEFICIENTE_3_DO_OXIG_NIO"]},"position":4},{"id":"v5-chem-stoich-practice-05","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"CALCULATE","contextFamily":"CERAMIC_PROCESS_PERCENT_YIELD","statement":"Um processo cerâmico tinha rendimento teórico de 20 kg de produto e forneceu 14 kg após a separação. Qual foi o rendimento percentual?","options":["60%","70%","140%","35%"],"correctAnswer":"70%","explanation":"Rendimento percentual = rendimento real ÷ rendimento teórico × 100. Portanto, 14 ÷ 20 × 100 = 70%.","errorFocus":"Dividir o rendimento teórico pelo real ou inverter numerador e denominador.","hint":"Coloque a quantidade realmente obtida no numerador e a quantidade prevista no denominador.","misconceptions":{"60%":["DIVIDIR_O_RENDIMENTO_TE_RICO_PELO_REAL_OU_INVERTER_NUMERADOR_E_DENOMINADOR"]},"position":5},{"id":"v5-chem-stoich-transfer-01","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"PLAN","contextFamily":"AMMONIA_FEEDSTOCK_REQUIREMENT","statement":"Na síntese N₂ + 3 H₂ → 2 NH₃, uma fábrica planeja produzir 8 mol de NH₃ sem sobra de reagentes. Quantos mol de N₂ e H₂ são necessários?","options":["4 mol de N₂ e 12 mol de H₂.","8 mol de N₂ e 12 mol de H₂.","4 mol de N₂ e 8 mol de H₂.","12 mol de N₂ e 4 mol de H₂."],"correctAnswer":"4 mol de N₂ e 12 mol de H₂.","explanation":"A razão 1:3:2 deve ser multiplicada por 4 para que o produto passe de 2 para 8 mol. Isso exige 4 mol de N₂ e 12 mol de H₂.","errorFocus":"Multiplicar somente o coeficiente do produto ou associar os coeficientes às espécies erradas.","hint":"Encontre o fator comum entre 2 mol de NH₃ e 8 mol; aplique-o aos dois reagentes.","misconceptions":{"8 mol de N₂ e 12 mol de H₂.":["MULTIPLICAR_SOMENTE_O_COEFICIENTE_DO_PRODUTO_OU_ASSOCIAR_OS_COEFICIENTES_S_ESP_CIES_ERRADAS"]},"position":1},{"id":"v5-chem-stoich-transfer-02","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"CALCULATE","contextFamily":"LIMESTONE_ACID_NEUTRALIZATION","statement":"A reação CaCO₃ + 2 HCl → CaCl₂ + CO₂ + H₂O ocorre com HCl em excesso. Considere M(CaCO₃) = 100 g/mol e M(CO₂) = 44 g/mol. Qual massa de CO₂ pode resultar de 50 g de CaCO₃?","options":["44 g","22 g","50 g","11 g"],"correctAnswer":"22 g","explanation":"50 g de CaCO₃ correspondem a 0,50 mol. A razão CaCO₃:CO₂ é 1:1, então formam-se 0,50 mol de CO₂, ou 22 g.","errorFocus":"Usar a proporção entre massas como se massa e mol tivessem a mesma razão dos coeficientes.","hint":"Converta 50 g de CaCO₃ em mol, aplique a razão 1:1 e converta o CO₂ de volta para gramas.","misconceptions":{"44 g":["USAR_A_PROPOR_O_ENTRE_MASSAS_COMO_SE_MASSA_E_MOL_TIVESSEM_A_MESMA_RAZ_O_DOS_COEFICIENTES"]},"position":2},{"id":"v5-chem-stoich-transfer-03","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"INTERPRET","contextFamily":"BAKING_SODA_GAS_QUANTITY","statement":"No modelo 2 NaHCO₃ → Na₂CO₃ + CO₂ + H₂O, considere M(NaHCO₃) = 84 g/mol. Uma amostra de 252 g se decompõe completamente. Quantos mol de CO₂ são previstos?","options":["3 mol","2 mol","1,5 mol","0,5 mol"],"correctAnswer":"1,5 mol","explanation":"252 g ÷ 84 g/mol = 3 mol de NaHCO₃. Como 2 mol do reagente formam 1 mol de CO₂, a quantidade prevista é 1,5 mol.","errorFocus":"Confundir a quantidade do reagente com a do produto ou esquecer o coeficiente 2.","hint":"Primeiro descubra quantos mol de NaHCO₃ existem; depois use a razão 1 mol CO₂ para 2 mol NaHCO₃.","misconceptions":{"3 mol":["CONFUNDIR_A_QUANTIDADE_DO_REAGENTE_COM_A_DO_PRODUTO_OU_ESQUECER_O_COEFICIENTE_2"]},"position":3},{"id":"v5-chem-stoich-transfer-04","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"ANTACID_LIMITING_REACTANT","statement":"No modelo NaHCO₃ + HCl → NaCl + CO₂ + H₂O, um ensaio usa 0,75 mol de NaHCO₃ e 0,50 mol de HCl. Admitindo reação completa, qual conclusão está correta?","options":["NaHCO₃ é limitante e podem se formar 0,75 mol de CO₂.","Nenhum reagente é limitante porque a equação tem coeficientes iguais.","HCl é limitante e podem se formar 0,75 mol de CO₂.","HCl é limitante e podem se formar 0,50 mol de CO₂."],"correctAnswer":"HCl é limitante e podem se formar 0,50 mol de CO₂.","explanation":"A proporção entre NaHCO₃, HCl e CO₂ é 1:1:1. Os 0,50 mol de HCl reagem com 0,50 mol de NaHCO₃ e limitam a formação a 0,50 mol de CO₂.","errorFocus":"Comparar apenas os nomes ou massas dos reagentes, em vez de comparar suas quantidades com a proporção da equação.","hint":"Para coeficientes iguais, o menor número de mol limita; o produto acompanha esse mesmo número.","misconceptions":{"NaHCO₃ é limitante e podem se formar 0,75 mol de CO₂.":["COMPARAR_APENAS_OS_NOMES_OU_MASSAS_DOS_REAGENTES_EM_VEZ_DE_COMPARAR_SUAS_QUANTIDADES_COM_A_PROPOR_O_DA_EQUA_O"]},"position":4},{"id":"v5-chem-stoich-transfer-05","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"INDUSTRIAL_PRODUCT_RECOVERY","statement":"Uma linha de produção previa teoricamente 250 kg de um material e recuperou 210 kg após purificação. Qual leitura combina corretamente rendimento e perda de processo?","options":["O rendimento foi 84%; a diferença de 40 kg não deve ser chamada de produto recuperado.","O rendimento foi 119%; a massa recuperada supera a prevista.","O rendimento foi 16%; esse valor é a razão entre a perda e o total previsto.","O rendimento foi 40%; esse valor é a massa que não foi recuperada."],"correctAnswer":"O rendimento foi 84%; a diferença de 40 kg não deve ser chamada de produto recuperado.","explanation":"210 ÷ 250 × 100 = 84%. Os 40 kg são a diferença entre previsão e recuperação, não o rendimento percentual.","errorFocus":"Confundir a massa perdida com a razão percentual ou inverter a fração.","hint":"Calcule primeiro a fração 210/250; só depois transforme-a em porcentagem.","misconceptions":{"O rendimento foi 119%; a massa recuperada supera a prevista.":["CONFUNDIR_A_MASSA_PERDIDA_COM_A_RAZ_O_PERCENTUAL_OU_INVERTER_A_FRA_O"]},"position":5},{"id":"v5-chem-stoich-lock-01","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"INTEGRATE","contextFamily":"ALUMINUM_CHLORIDE_MASS_LIMITING","statement":"Na reação 2 Al + 3 Cl₂ → 2 AlCl₃, misturam-se 54 g de Al e 284 g de Cl₂. Considere M(Al) = 27 g/mol e M(Cl₂) = 71 g/mol. Qual é o resultado teórico?","options":["Cl₂ é limitante e podem se formar 4 mol de AlCl₃.","Al é limitante e podem se formar 2 mol de AlCl₃.","Al é limitante e podem se formar 4 mol de AlCl₃.","Os reagentes estão na proporção exata e formam 3 mol de AlCl₃."],"correctAnswer":"Al é limitante e podem se formar 2 mol de AlCl₃.","explanation":"54 g Al = 2 mol e 284 g Cl₂ = 4 mol. Dois mol de Al exigem 3 mol de Cl₂; portanto, Al limita e 2 mol de AlCl₃ são previstos.","errorFocus":"Escolher o reagente limitante comparando apenas os mol disponíveis, sem dividir pela proporção da equação.","hint":"Compare 2/2 para Al e 4/3 para Cl₂: o menor quociente indica quanto a reação pode avançar.","misconceptions":{"Cl₂ é limitante e podem se formar 4 mol de AlCl₃.":["ESCOLHER_O_REAGENTE_LIMITANTE_COMPARANDO_APENAS_OS_MOL_DISPON_VEIS_SEM_DIVIDIR_PELA_PROPOR_O_DA_EQUA_O"]},"position":1},{"id":"v5-chem-stoich-lock-02","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"INTEGRATE","contextFamily":"MAGNESIUM_OXIDE_MASS_BALANCE","statement":"A reação 2 Mg + O₂ → 2 MgO recebe 48 g de Mg e 48 g de O₂. Considere M(Mg) = 24 g/mol e M(O₂) = 32 g/mol; M(MgO) = 40 g/mol. Qual massa teórica de MgO pode ser formada?","options":["40 g","96 g","80 g","120 g"],"correctAnswer":"80 g","explanation":"48 g Mg = 2 mol, enquanto 48 g O₂ = 1,5 mol. Os 2 mol de Mg exigem 1 mol de O₂, então Mg limita e formam-se 2 mol MgO = 80 g.","errorFocus":"Supor que o reagente com menor massa sempre limita ou esquecer de converter cada massa em mol.","hint":"Converta as duas massas; compare mol disponíveis divididos pelos coeficientes e só então converta o produto em gramas.","misconceptions":{"40 g":["SUPOR_QUE_O_REAGENTE_COM_MENOR_MASSA_SEMPRE_LIMITA_OU_ESQUECER_DE_CONVERTER_CADA_MASSA_EM_MOL"]},"position":2},{"id":"v5-chem-stoich-lock-03","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"CALCIUM_CARBONATE_REAL_YIELD","statement":"Na decomposição CaCO₃ → CaO + CO₂, 250 g de CaCO₃ são processados. Use M(CaCO₃) = 100 g/mol e M(CaO) = 56 g/mol. Se forem obtidos 112 g de CaO, qual foi o rendimento percentual?","options":["56%","112%","125%","80%"],"correctAnswer":"80%","explanation":"250 g de CaCO₃ são 2,5 mol; a razão 1:1 prevê 2,5 mol de CaO, ou 140 g. O rendimento é 112/140 × 100 = 80%.","errorFocus":"Usar a massa inicial como rendimento teórico sem aplicar a razão molar e a massa molar do produto.","hint":"Calcule primeiro a massa teórica de CaO; depois divida a massa real por esse valor.","misconceptions":{"56%":["USAR_A_MASSA_INICIAL_COMO_RENDIMENTO_TE_RICO_SEM_APLICAR_A_RAZ_O_MOLAR_E_A_MASSA_MOLAR_DO_PRODUTO"]},"position":3},{"id":"v5-chem-stoich-review-01","purpose":"REVIEW","difficulty":"EASY","cognitiveProcess":"DISTINGUISH","contextFamily":"WATER_COEFFICIENT_VS_SUBSCRIPT","statement":"Na equação 2 H₂ + O₂ → 2 H₂O, o que representa o coeficiente 2 diante de H₂O?","options":["Uma proporção de duas unidades de H₂O para cada unidade de O₂ na equação balanceada.","Dois átomos de hidrogênio dentro de cada molécula de água.","Dois gramas de água formados em qualquer escala.","Dois mol de água obrigatoriamente, mesmo que a reação ocorra em outra escala."],"correctAnswer":"Uma proporção de duas unidades de H₂O para cada unidade de O₂ na equação balanceada.","explanation":"O coeficiente dá a proporção entre quantidades de partículas ou mol. O índice 2 em H₂O indica dois átomos de hidrogênio em cada molécula.","errorFocus":"Confundir coeficiente, índice da fórmula, massa e quantidade absoluta.","hint":"Leia o número antes da fórmula como proporção da reação e o número pequeno como composição da partícula.","misconceptions":{"Dois átomos de hidrogênio dentro de cada molécula de água.":["CONFUNDIR_COEFICIENTE_NDICE_DA_F_RMULA_MASSA_E_QUANTIDADE_ABSOLUTA"]},"position":1},{"id":"v5-chem-stoich-review-02","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"APPLY","contextFamily":"CHLORATE_SPACED_RATIO","statement":"Para 2 KClO₃ → 2 KCl + 3 O₂, quantos mol de O₂ correspondem a 0,4 mol de KClO₃?","options":["0,4 mol","0,6 mol","0,8 mol","1,2 mol"],"correctAnswer":"0,6 mol","explanation":"A razão O₂/KClO₃ é 3/2. Logo, 0,4 × 3/2 = 0,6 mol de O₂.","errorFocus":"Aplicar o fator 2/3 quando a pergunta pede produto por reagente.","hint":"Monte a fração com o produto no numerador: 3 mol O₂ / 2 mol KClO₃.","misconceptions":{"0,4 mol":["APLICAR_O_FATOR_2_3_QUANDO_A_PERGUNTA_PEDE_PRODUTO_POR_REAGENTE"]},"position":2},{"id":"v5-chem-stoich-review-03","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"PROPANE_COMBUSTION_LIMITING","statement":"Na combustão C₃H₈ + 5 O₂ → 3 CO₂ + 4 H₂O, há 1 mol de C₃H₈ e 4 mol de O₂. Qual resultado é previsto?","options":["C₃H₈ é limitante e podem se formar 3 mol de CO₂.","O₂ é limitante e podem se formar 4 mol de CO₂.","O₂ é limitante e podem se formar 2,4 mol de CO₂.","Os reagentes estão na proporção estequiométrica e formam 3 mol de CO₂."],"correctAnswer":"O₂ é limitante e podem se formar 2,4 mol de CO₂.","explanation":"Um mol de C₃H₈ exigiria 5 mol de O₂, mas há apenas 4. A quantidade de CO₂ é 4 × 3/5 = 2,4 mol.","errorFocus":"Achar que uma mistura é estequiométrica por ter números próximos ou usar o coeficiente do produto sem limitar pelos reagentes.","hint":"Calcule quanto CO₂ cada reagente poderia produzir; o menor resultado identifica o limitante.","misconceptions":{"C₃H₈ é limitante e podem se formar 3 mol de CO₂.":["ACHAR_QUE_UMA_MISTURA_ESTEQUIOM_TRICA_POR_TER_N_MEROS_PR_XIMOS_OU_USAR_O_COEFICIENTE_DO_PRODUTO_SEM_LIMITAR_PELOS_REAGENTES"]},"position":3},{"id":"v5-chem-stoich-review-04","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"CALCULATE","contextFamily":"SALT_MOLAR_AMOUNT_RECOVERY","statement":"Na reação HCl + NaOH → NaCl + H₂O, considere M(NaCl) = 58,5 g/mol. Uma amostra contém 117 g de NaCl. Quantos mol de NaCl ela representa?","options":["1 mol","58,5 mol","0,5 mol","2 mol"],"correctAnswer":"2 mol","explanation":"A quantidade de matéria é n = m/M. Portanto, 117 g ÷ 58,5 g/mol = 2 mol.","errorFocus":"Multiplicar massa por massa molar ou esquecer a unidade mol na divisão.","hint":"Use n = m/M; gramas divididos por gramas por mol resultam em mol.","misconceptions":{"1 mol":["MULTIPLICAR_MASSA_POR_MASSA_MOLAR_OU_ESQUECER_A_UNIDADE_MOL_NA_DIVIS_O"]},"position":4},{"id":"v5-chem-stoich-review-05","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"YIELD_CLAIM_AUDIT","statement":"Um relatório informa rendimento teórico de 40 g e rendimento real de 46 g, atribuindo rendimento de 115%. Qual análise é mais adequada para um produto isolado e seco?","options":["A razão calculada é 115%, mas o resultado pede verificar pureza, secagem, medição e pressupostos antes de tratá-lo como rendimento químico acima do teórico.","O valor prova que a conservação da matéria foi violada.","O rendimento é necessariamente 85%, pois deve-se subtrair 40 de 46.","O cálculo está errado; todo rendimento real precisa ser menor que 40 g, qualquer que seja a medição."],"correctAnswer":"A razão calculada é 115%, mas o resultado pede verificar pureza, secagem, medição e pressupostos antes de tratá-lo como rendimento químico acima do teórico.","explanation":"46/40 × 100 = 115%, mas uma massa aparente acima do teórico pode indicar umidade, impurezas, erro de medição ou modelo incompleto. O cálculo não valida sozinho a qualidade da amostra.","errorFocus":"Aceitar ou rejeitar o número sem separar o cálculo da avaliação da amostra e das medições.","hint":"Confira a fórmula percentual e depois verifique se a massa real representa produto puro, seco e corretamente medido.","misconceptions":{"O valor prova que a conservação da matéria foi violada.":["ACEITAR_OU_REJEITAR_O_N_MERO_SEM_SEPARAR_O_C_LCULO_DA_AVALIA_O_DA_AMOSTRA_E_DAS_MEDI_ES"]},"position":5},{"id":"v16-chemistry-stoichiometry-001","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"V16_CHEMISTRY_STOICHIOMETRY_BALANCE_01","statement":"A reação de formação da água é representada por H₂ + O₂ → H₂O. Que ajuste conserva os átomos de cada elemento?","options":["2 H₂ + O₂ → 2 H₂O.","H₂ + O₂ → H₂O₂, pois basta mudar um índice.","H₂ + 2 O₂ → H₂O.","2 H₂ + 2 O₂ → H₂O."],"correctAnswer":"2 H₂ + O₂ → 2 H₂O.","explanation":"A resposta usa a equação balanceada, unidades e limites da mistura para justificar o cálculo. Conte os átomos dos dois lados e altere coeficientes, não índices das fórmulas.","hint":"Escreva a equação balanceada, destaque as unidades e confira o reagente limitante.","errorFocus":"CHEMISTRY_STOICHIOMETRY_RATIO_AND_UNIT","misconceptions":{"H₂ + O₂ → H₂O₂, pois basta mudar um índice.":["CHEMISTRY_STOICHIOMETRY_RATIO_AND_UNIT"]},"position":1},{"id":"v16-chemistry-stoichiometry-002","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"DISTINGUISH","contextFamily":"V16_CHEMISTRY_STOICHIOMETRY_BALANCE_02","statement":"A reação de formação da água é representada por H₂ + O₂ → H₂O. Qual critério deve orientar a análise?","options":["H₂ + O₂ → H₂O₂, pois basta mudar um índice.","Use Conte os átomos dos dois lados e altere coeficientes, não índices das fórmulas.","H₂ + 2 O₂ → H₂O.","2 H₂ + 2 O₂ → H₂O."],"correctAnswer":"Use Conte os átomos dos dois lados e altere coeficientes, não índices das fórmulas.","explanation":"A resposta usa a equação balanceada, unidades e limites da mistura para justificar o cálculo. Conte os átomos dos dois lados e altere coeficientes, não índices das fórmulas.","hint":"Escreva a equação balanceada, destaque as unidades e confira o reagente limitante.","errorFocus":"CHEMISTRY_STOICHIOMETRY_RATIO_AND_UNIT","misconceptions":{"H₂ + O₂ → H₂O₂, pois basta mudar um índice.":["CHEMISTRY_STOICHIOMETRY_RATIO_AND_UNIT"]},"position":2},{"id":"v16-chemistry-stoichiometry-003","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"COMPARE","contextFamily":"V16_CHEMISTRY_STOICHIOMETRY_BALANCE_03","statement":"A reação de formação da água é representada por H₂ + O₂ → H₂O. Como transferir esse raciocínio para outro caso?","options":["H₂ + O₂ → H₂O₂, pois basta mudar um índice.","H₂ + 2 O₂ → H₂O.","Balanceie outra equação simples conferindo cada elemento após o ajuste.","2 H₂ + 2 O₂ → H₂O."],"correctAnswer":"Balanceie outra equação simples conferindo cada elemento após o ajuste.","explanation":"A resposta usa a equação balanceada, unidades e limites da mistura para justificar o cálculo. Conte os átomos dos dois lados e altere coeficientes, não índices das fórmulas.","hint":"Escreva a equação balanceada, destaque as unidades e confira o reagente limitante.","errorFocus":"CHEMISTRY_STOICHIOMETRY_RATIO_AND_UNIT","misconceptions":{"H₂ + O₂ → H₂O₂, pois basta mudar um índice.":["CHEMISTRY_STOICHIOMETRY_RATIO_AND_UNIT"]},"position":3},{"id":"v16-chemistry-stoichiometry-004","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"INTERPRET","contextFamily":"V16_CHEMISTRY_STOICHIOMETRY_BALANCE_04","statement":"A reação de formação da água é representada por H₂ + O₂ → H₂O. Qual conclusão deve ser evitada?","options":["H₂ + O₂ → H₂O₂, pois basta mudar um índice.","H₂ + 2 O₂ → H₂O.","2 H₂ + 2 O₂ → H₂O.","Evite alterar índices das fórmulas para fazer uma equação parecer balanceada."],"correctAnswer":"Evite alterar índices das fórmulas para fazer uma equação parecer balanceada.","explanation":"A resposta usa a equação balanceada, unidades e limites da mistura para justificar o cálculo. Conte os átomos dos dois lados e altere coeficientes, não índices das fórmulas.","hint":"Escreva a equação balanceada, destaque as unidades e confira o reagente limitante.","errorFocus":"CHEMISTRY_STOICHIOMETRY_RATIO_AND_UNIT","misconceptions":{"H₂ + O₂ → H₂O₂, pois basta mudar um índice.":["CHEMISTRY_STOICHIOMETRY_RATIO_AND_UNIT"]},"position":4},{"id":"v16-chemistry-stoichiometry-005","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"V16_CHEMISTRY_STOICHIOMETRY_BALANCE_05","statement":"A reação de formação da água é representada por H₂ + O₂ → H₂O. Que evidência deve ser conferida primeiro?","options":["Confira quantidade de átomos de hidrogênio e oxigênio em cada lado.","H₂ + O₂ → H₂O₂, pois basta mudar um índice.","H₂ + 2 O₂ → H₂O.","2 H₂ + 2 O₂ → H₂O."],"correctAnswer":"Confira quantidade de átomos de hidrogênio e oxigênio em cada lado.","explanation":"A resposta usa a equação balanceada, unidades e limites da mistura para justificar o cálculo. Conte os átomos dos dois lados e altere coeficientes, não índices das fórmulas.","hint":"Escreva a equação balanceada, destaque as unidades e confira o reagente limitante.","errorFocus":"CHEMISTRY_STOICHIOMETRY_RATIO_AND_UNIT","misconceptions":{"H₂ + O₂ → H₂O₂, pois basta mudar um índice.":["CHEMISTRY_STOICHIOMETRY_RATIO_AND_UNIT"]},"position":5},{"id":"v16-chemistry-stoichiometry-006","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"DISTINGUISH","contextFamily":"V16_CHEMISTRY_STOICHIOMETRY_BALANCE_06","statement":"A reação de formação da água é representada por H₂ + O₂ → H₂O. Qual é o próximo passo mais cuidadoso?","options":["H₂ + O₂ → H₂O₂, pois basta mudar um índice.","contar os átomos antes e depois e ajustar os coeficientes mínimos","H₂ + 2 O₂ → H₂O.","2 H₂ + 2 O₂ → H₂O."],"correctAnswer":"contar os átomos antes e depois e ajustar os coeficientes mínimos","explanation":"A resposta usa a equação balanceada, unidades e limites da mistura para justificar o cálculo. Conte os átomos dos dois lados e altere coeficientes, não índices das fórmulas.","hint":"Escreva a equação balanceada, destaque as unidades e confira o reagente limitante.","errorFocus":"CHEMISTRY_STOICHIOMETRY_RATIO_AND_UNIT","misconceptions":{"H₂ + O₂ → H₂O₂, pois basta mudar um índice.":["CHEMISTRY_STOICHIOMETRY_RATIO_AND_UNIT"]},"position":6},{"id":"v16-chemistry-stoichiometry-007","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"COMPARE","contextFamily":"V16_CHEMISTRY_STOICHIOMETRY_BALANCE_07","statement":"A reação de formação da água é representada por H₂ + O₂ → H₂O. Qual limite deve aparecer na resposta?","options":["H₂ + O₂ → H₂O₂, pois basta mudar um índice.","H₂ + 2 O₂ → H₂O.","Mantenha a conclusão ligada a a conservação de átomos representada pela equação.","2 H₂ + 2 O₂ → H₂O."],"correctAnswer":"Mantenha a conclusão ligada a a conservação de átomos representada pela equação.","explanation":"A resposta usa a equação balanceada, unidades e limites da mistura para justificar o cálculo. Conte os átomos dos dois lados e altere coeficientes, não índices das fórmulas.","hint":"Escreva a equação balanceada, destaque as unidades e confira o reagente limitante.","errorFocus":"CHEMISTRY_STOICHIOMETRY_RATIO_AND_UNIT","misconceptions":{"H₂ + O₂ → H₂O₂, pois basta mudar um índice.":["CHEMISTRY_STOICHIOMETRY_RATIO_AND_UNIT"]},"position":7},{"id":"v16-chemistry-stoichiometry-008","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"INTERPRET","contextFamily":"V16_CHEMISTRY_STOICHIOMETRY_BALANCE_08","statement":"A reação de formação da água é representada por H₂ + O₂ → H₂O. Que comparação é mais justa?","options":["H₂ + O₂ → H₂O₂, pois basta mudar um índice.","H₂ + 2 O₂ → H₂O.","2 H₂ + 2 O₂ → H₂O.","Compare átomos nos reagentes e nos produtos."],"correctAnswer":"Compare átomos nos reagentes e nos produtos.","explanation":"A resposta usa a equação balanceada, unidades e limites da mistura para justificar o cálculo. Conte os átomos dos dois lados e altere coeficientes, não índices das fórmulas.","hint":"Escreva a equação balanceada, destaque as unidades e confira o reagente limitante.","errorFocus":"CHEMISTRY_STOICHIOMETRY_RATIO_AND_UNIT","misconceptions":{"H₂ + O₂ → H₂O₂, pois basta mudar um índice.":["CHEMISTRY_STOICHIOMETRY_RATIO_AND_UNIT"]},"position":8},{"id":"v16-chemistry-stoichiometry-009","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"V16_CHEMISTRY_STOICHIOMETRY_BALANCE_09","statement":"A reação de formação da água é representada por H₂ + O₂ → H₂O. Qual seria um exagero interpretativo?","options":["Seria exagero alterar índices das fórmulas para fazer uma equação parecer balanceada.","H₂ + O₂ → H₂O₂, pois basta mudar um índice.","H₂ + 2 O₂ → H₂O.","2 H₂ + 2 O₂ → H₂O."],"correctAnswer":"Seria exagero alterar índices das fórmulas para fazer uma equação parecer balanceada.","explanation":"A resposta usa a equação balanceada, unidades e limites da mistura para justificar o cálculo. Conte os átomos dos dois lados e altere coeficientes, não índices das fórmulas.","hint":"Escreva a equação 